# END BUNDLED APP ICONS
function Get-AppIcon([string]$id) {
 $definition=$iconDefinitions.$id
 if(-not $definition){throw "Missing app icon: $id"}
 $drawing=[Windows.Media.DrawingGroup]::new()
 $bounds=[Windows.Media.RectangleGeometry]::new([Windows.Rect]::new(0,0,24,24))
 $drawing.Children.Add([Windows.Media.GeometryDrawing]::new([Windows.Media.Brushes]::Transparent,$null,$bounds))
 $brush=[Windows.Media.BrushConverter]::new().ConvertFromString($definition.Color)
 $geometry=[Windows.Media.Geometry]::Parse($definition.Path)
 $drawing.Children.Add([Windows.Media.GeometryDrawing]::new($brush,$null,$geometry))
 $icon=[Windows.Media.DrawingImage]::new($drawing)
 $icon.Freeze()
 return $icon
}
function Save-Selection {
 # DrawingImage objects belong to the UI; persist only user choices and results.
 Save-Json @($rows | Select-Object Id,Selected,Status) $savedPath
}
$lockName=if($ValidateUi){'Local\WinProvisionAppPickerTests'}elseif($Configure){'Local\WinProvisionAppConfiguration'}else{'Local\WinProvisionAppPicker'}
$uiLock=[Threading.Mutex]::new($false,$lockName)
$uiLocked=$false
try { $uiLocked=$uiLock.WaitOne(0) } catch [Threading.AbandonedMutexException] { $uiLocked=$true }
if(-not $uiLocked){$uiLock.Dispose();exit}
$script:running=$false
$script:workerProcess=$null
$script:activeJob=$null
$dataDir=Join-Path $env:LOCALAPPDATA 'WinProvision\Apps'
$savedPath=Join-Path $dataDir 'selection.json'
$saved=@()
$autoStart=$false
if(-not $Preview) {
 New-Item -ItemType Directory -Path $dataDir -Force | Out-Null
 try { if(Test-Path -LiteralPath $savedPath){$saved=@(Get-Content -LiteralPath $savedPath -Raw | ConvertFrom-Json)} } catch { $saved=@() }
 if($initialPlan.Mode -eq 'BeforeBoot' -and -not (Test-Path -LiteralPath (Join-Path $dataDir 'autostart-attempted'))){
  $saved=@($initialPlan.Ids | ForEach-Object { [pscustomobject]@{Id=$_;Selected=$true;Status='Available'} })
  $autoStart=$true
 }
}
if($Configure){$request=Get-Content -LiteralPath $SelectionPath -Raw | ConvertFrom-Json;$saved=@($request.Ids | ForEach-Object { [pscustomobject]@{Id=$_;Selected=$true;Status='Available'} })}
$rows=New-Object 'System.Collections.ObjectModel.ObservableCollection[Object]'
foreach($app in $catalog) {
 $previous=$saved | Where-Object Id -eq $app.Id | Select-Object -First 1
 $rows.Add([pscustomobject]@{Id=$app.Id;Name=$app.Name;Category=$app.Category;Description=$app.Description;Icon=(Get-AppIcon $app.Id);Selected=([bool]$previous.Selected);Status=if($previous.Status -in @('Completed','Concluído')){'Completed'}else{'Available'};Compatibility='Windows 10 and 11 · current catalog version'})
}
[xml]$xaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="WinProvision · Your apps" Width="1080" Height="800" MinWidth="800" MinHeight="640" WindowStartupLocation="CenterScreen" Background="#F3F6F5" FontFamily="Segoe UI" FontSize="14" Foreground="#172A34">
 <Window.Resources>
  <Style TargetType="Button"><Setter Property="Padding" Value="16,10"/><Setter Property="Margin" Value="0,0,8,0"/><Setter Property="Background" Value="White"/><Setter Property="BorderBrush" Value="#CCD8D3"/><Setter Property="Cursor" Value="Hand"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="7" Padding="{TemplateBinding Padding}"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsEnabled" Value="False"><Setter Property="Opacity" Value="0.45"/></Trigger><Trigger Property="IsMouseOver" Value="True"><Setter Property="Opacity" Value="0.8"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
  <Style TargetType="TextBlock"><Setter Property="TextWrapping" Value="Wrap"/></Style>
 </Window.Resources>
 <Grid Margin="30,24">
  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
  <StackPanel><TextBlock Text="WINPROVISION  /  GETTING STARTED" Foreground="#0B7467" FontWeight="Bold" FontSize="12"/><TextBlock Text="Your Windows. Your apps." FontSize="30" FontWeight="SemiBold" Margin="0,10,0,6"/><TextBlock Text="Choose the apps you use and install them here. You can also come back later." Foreground="#607480"/></StackPanel>
  <Border Grid.Row="1" Background="#E4EFEB" Padding="14,10" CornerRadius="8" Margin="0,18,0,16"><DockPanel><Button Name="Store" Content="Open Microsoft Store" DockPanel.Dock="Right"/><TextBlock Name="Environment" VerticalAlignment="Center" Text="An internet connection is required. Windows may ask for permission to install."/></DockPanel></Border>
  <StackPanel Grid.Row="2" Margin="0,0,0,12"><TextBlock Text="Search apps" FontSize="12" Margin="0,0,0,5"/><TextBox Name="Search" Padding="12,9" ToolTip="Search by name or category" AutomationProperties.Name="Search apps"/>
   <ListBox Name="Category" Margin="0,12,0,0" BorderThickness="0" Background="Transparent" ScrollViewer.HorizontalScrollBarVisibility="Disabled" AutomationProperties.Name="App categories">
    <ListBox.ItemsPanel><ItemsPanelTemplate><WrapPanel/></ItemsPanelTemplate></ListBox.ItemsPanel>
    <ListBox.ItemContainerStyle><Style TargetType="ListBoxItem"><Setter Property="Margin" Value="0,0,6,6"/><Setter Property="Cursor" Value="Hand"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ListBoxItem"><Border Name="TabBorder" Padding="12,7" CornerRadius="7" BorderThickness="1" BorderBrush="#D5DFDC" Background="White"><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property="IsSelected" Value="True"><Setter TargetName="TabBorder" Property="Background" Value="#0B7467"/><Setter Property="Foreground" Value="White"/><Setter Property="FontWeight" Value="SemiBold"/></Trigger><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="TabBorder" Property="BorderBrush" Value="#0B7467"/></Trigger><Trigger Property="IsKeyboardFocused" Value="True"><Setter TargetName="TabBorder" Property="BorderBrush" Value="#0B7467"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style></ListBox.ItemContainerStyle>
   </ListBox>
  </StackPanel>
  <ListBox Name="Apps" Grid.Row="3" BorderThickness="0" Background="Transparent" ScrollViewer.HorizontalScrollBarVisibility="Disabled" HorizontalContentAlignment="Stretch" SelectionMode="Single">
   <ListBox.GroupStyle><GroupStyle><GroupStyle.HeaderTemplate><DataTemplate><Border Padding="2,14,2,8"><StackPanel Orientation="Horizontal"><TextBlock Text="{Binding Name}" FontSize="18" FontWeight="SemiBold" Foreground="#0B7467"/><TextBlock Text="{Binding ItemCount, StringFormat=' ({0})'}" FontSize="14" Foreground="#607480" VerticalAlignment="Center"/></StackPanel></Border></DataTemplate></GroupStyle.HeaderTemplate></GroupStyle></ListBox.GroupStyle>
   <ListBox.ItemContainerStyle><Style TargetType="ListBoxItem"><Setter Property="Padding" Value="0"/><Setter Property="Margin" Value="0,0,0,8"/><Setter Property="HorizontalContentAlignment" Value="Stretch"/></Style></ListBox.ItemContainerStyle>
   <ListBox.ItemTemplate><DataTemplate><Border Background="White" BorderBrush="#DCE5E1" BorderThickness="1" CornerRadius="9" Padding="16,12"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="36"/><ColumnDefinition Width="62"/><ColumnDefinition Width="*"/><ColumnDefinition Width="125"/></Grid.ColumnDefinitions><CheckBox IsChecked="{Binding Selected,Mode=TwoWay,UpdateSourceTrigger=PropertyChanged}" VerticalAlignment="Center" AutomationProperties.Name="{Binding Name}"/><Border Grid.Column="1" Width="46" Height="46" CornerRadius="10" Background="#F1F5F3" HorizontalAlignment="Left" VerticalAlignment="Center"><Image Source="{Binding Icon}" Width="30" Height="30" Stretch="Uniform" RenderOptions.BitmapScalingMode="HighQuality" Focusable="False"/></Border><StackPanel Grid.Column="2"><TextBlock Text="{Binding Name}" FontSize="17" FontWeight="SemiBold"/><TextBlock Text="{Binding Description}" Foreground="#607480" Margin="0,3,8,3"/><TextBlock Text="{Binding Compatibility}" Foreground="#73847D" FontSize="11"/></StackPanel><StackPanel Grid.Column="3" VerticalAlignment="Center"><TextBlock Text="{Binding Category}" Foreground="#607480" FontSize="12" HorizontalAlignment="Right"/><TextBlock Text="{Binding Status}" Foreground="#0B7467" FontWeight="SemiBold" HorizontalAlignment="Right" Margin="0,5,0,0"/></StackPanel></Grid></Border></DataTemplate></ListBox.ItemTemplate>
  </ListBox>
  <StackPanel Grid.Row="4" Margin="0,14,0,12"><TextBlock Name="Status" Text="No apps selected." FontWeight="SemiBold"/><ProgressBar Name="Progress" Height="5" Margin="0,9,0,8" Foreground="#0B7467"/><TextBlock Name="InstallTerms" Text="By installing, you accept the terms of the selected apps and the WinGet source. No apps will be installed until you click Install." Foreground="#607480" FontSize="12"/></StackPanel>
  <DockPanel Grid.Row="5"><StackPanel Orientation="Horizontal" DockPanel.Dock="Right"><Button Name="Later" Content="Maybe later"/><Button Name="Install" Content="Install selected" Background="#0B7467" Foreground="White" Margin="0"/></StackPanel><StackPanel Orientation="Horizontal"><Button Name="Logs" Content="View logs"/><Button Name="Stop" Content="Stop after current app" Visibility="Collapsed"/></StackPanel></DockPanel>
 </Grid>
</Window>
'@
$window=[Windows.Markup.XamlReader]::Load([Xml.XmlNodeReader]::new($xaml))
foreach($name in @('Apps','Search','Category','Environment','Status','Progress','Install','Later','Logs','Stop','Store','InstallTerms')) { Set-Variable -Name $name -Value $window.FindName($name) }
$Apps.ItemsSource=$rows
$view=[Windows.Data.CollectionViewSource]::GetDefaultView($rows)
[void]$view.GroupDescriptions.Add([Windows.Data.PropertyGroupDescription]::new('Category'))
[void]$Category.Items.Add('All apps')
foreach($name in @($catalog.Category | Select-Object -Unique)){[void]$Category.Items.Add($name)}
$Category.SelectedIndex=0
$view.Filter={param($row) ($row.Name+' '+$row.Category+' '+$row.Description).IndexOf($Search.Text,[StringComparison]::OrdinalIgnoreCase) -ge 0 -and ($Category.SelectedIndex -eq 0 -or $row.Category -eq $Category.SelectedItem)}
$Search.Add_TextChanged({$view.Refresh()})
$Category.Add_SelectionChanged({$view.Refresh()})
if($Preview){$Environment.Text='INTERFACE PREVIEW · Installation is disabled. Nothing will be downloaded or installed.';$Store.IsEnabled=$false}
elseif(-not (Get-WingetPath)){$Environment.Text='App Installer is not available yet. Connect to the internet and update it in Microsoft Store.'}
if($autoStart){$InstallTerms.Text='These apps were selected and authorized in USB Builder. Installation starts automatically. Failures can be retried here.'}
if($Configure){$Environment.Text='CHOOSE NOW · Save the apps to install automatically on the new Windows. Nothing is installed on this PC.';$Later.Content='Cancel';$Logs.Visibility='Collapsed'}
$Store.Add_Click({Start-Process 'ms-windows-store://pdp/?ProductId=9NBLGGH4NNS1'})
$Logs.Add_Click({if(-not $Preview){Start-Process explorer.exe -ArgumentList ('"'+$dataDir+'"')}})
$Later.Add_Click({$window.Close()})
$Stop.Add_Click({if($script:activeJob){[IO.File]::WriteAllText((Join-Path $script:activeJob 'stop'),'stop');$Stop.IsEnabled=$false;$Status.Text='Waiting for the current app to finish. Remaining apps will be deferred.'}})
$Install.Add_Click({
 try {
  $selected=@($rows | Where-Object { $_.Selected -and $_.Status -ne 'Completed' })
  if($Configure){Save-Json @{Ids=@($selected.Id);Saved=$true} $SelectionPath;$window.Close();return}
  if($Preview -or $selected.Count -eq 0 -or $script:running){return}
  Save-Selection
  $script:activeJob=Join-Path $dataDir ([guid]::NewGuid().ToString('N'))
  New-Item -ItemType Directory -Path $script:activeJob | Out-Null
  Save-Json @{Ids=@($selected.Id)} (Join-Path $script:activeJob 'request.json')
  $script:workerProcess=Start-Process -FilePath "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList ('-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+$PSCommandPath+'" -Worker -JobPath "'+$script:activeJob+'"') -WindowStyle Hidden -PassThru
  $script:running=$true
  if($autoStart){[IO.File]::WriteAllText((Join-Path $dataDir 'autostart-attempted'),'Automatic installation requested once. Use the interface to retry failures.')}
  $Apps.IsEnabled=$false;$Search.IsEnabled=$false;$Category.IsEnabled=$false;$Install.IsEnabled=$false;$Later.IsEnabled=$false
  $Stop.Visibility='Visible';$Stop.IsEnabled=$true;$Progress.IsIndeterminate=$true
  $Status.Text='Preparing installation…'
 } catch { [Windows.MessageBox]::Show($_.Exception.Message,'WinProvision') | Out-Null }
})
$timer=[Windows.Threading.DispatcherTimer]::new()
$timer.Interval=[TimeSpan]::FromMilliseconds(750)
$timer.Add_Tick({
 try {
  if(-not $script:running){
   $count=@($rows | Where-Object { $_.Selected -and $_.Status -ne 'Completed' }).Count
   $Install.IsEnabled=($Configure -or ($count -gt 0 -and -not $Preview))
   $Install.Content=if($Configure){"Save selection ($count)"}else{"Install selected ($count)"}
   if(-not $script:activeJob){$Status.Text="$count app(s) selected."}
   return
  }
  $statusFile=Join-Path $script:activeJob 'status.json'
  $state=$null
  if(Test-Path -LiteralPath $statusFile){try{$state=Get-Content -LiteralPath $statusFile -Raw | ConvertFrom-Json}catch{return}}
  if($state){
   foreach($item in $state.Items){$row=$rows | Where-Object Id -eq $item.Id; if($row){$row.Status=$item.Status}}
   $view.Refresh()
   $Status.Text=$state.Message
   if($state.Items.Count -gt 0){$Progress.IsIndeterminate=$false;$Progress.Maximum=$state.Items.Count;$Progress.Value=@($state.Items | Where-Object { $_.Status -in @('Completed','Failed','Deferred') }).Count}
  }
  if($script:workerProcess.HasExited){
   if(-not $state -or -not $state.Done){$Status.Text='The installer was interrupted. Check the logs and try again.';foreach($row in $rows){if($row.Status -in @('Installing','Queued')){$row.Status='Failed'}}}
   $script:running=$false;$Progress.IsIndeterminate=$false;$Apps.IsEnabled=$true;$Search.IsEnabled=$true;$Category.IsEnabled=$true;$Later.IsEnabled=$true;$Later.Content='Finish';$Stop.Visibility='Collapsed'
   Save-Selection
   $view.Refresh()
  }
 } catch {$Status.Text='Unable to update progress: '+$_.Exception.Message}
})
$window.Add_Closing({param($sender,$eventArgs)
 if($script:running){$eventArgs.Cancel=$true;$Status.Text='Wait for installation to finish or choose Stop after current app.';return}
 if(-not $Preview){try{Save-Selection}catch{}}
})
$window.Add_ContentRendered({
 if($autoStart -and -not $script:running -and -not $Preview){
  $Install.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent))
 }
})
try {
 if($ValidateUi){
  if($rows.Count -ne 30 -or @($rows | Where-Object Selected).Count){throw 'Invalid initial catalog selection.'}
  if(@($rows | Where-Object { -not $_.Icon -or -not $_.Icon.IsFrozen -or $_.Icon.Width -le 0 }).Count){throw 'Bundled app icon failed to load.'}
  if($view.Groups.Count -ne 11 -or $Apps.GroupStyle.Count -ne 1){throw 'Visible category grouping failed.'}
  $Search.Text='firefox'; if(@($view).Count -ne 1 -or $view.Groups.Count -ne 1 -or $view.Groups[0].Name -ne 'Browsers'){throw 'Grouped search filter failed.'}
  $rows[0].Selected=$true
  $Search.Text='not-a-real-app'; if(@($view).Count -ne 0){throw 'Empty search failed.'}
  $Search.Text='';$Category.SelectedItem='Development';if(@($view).Count -ne 7){throw 'Category filter failed.'}
  $Category.SelectedIndex=0;if(@($view).Count -ne 30 -or $view.Groups.Count -ne 11 -or -not $rows[0].Selected){throw 'Selection preservation failed.'}
  Write-Output 'PASS: WPF layout loaded; empty selection, search, empty results, categories and hidden selection persistence verified. No apps installed.'
 } else {$timer.Start();[void]$window.ShowDialog()}
} finally {$timer.Stop();if($uiLocked){$uiLock.ReleaseMutex()};$uiLock.Dispose()}
